using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ANM.Anuncios;namespace GraphApi.Services.ANM.Anuncios{    public class AnunciosService : IAnunciosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public AnunciosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadAnuncios>> GetAnuncios(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM anm.vsAnuncios (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadAnuncios>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetAnunciosDynamic(            int? anuncioID,            string? titulo,            string? contenido,            DateTime? fechaPublicacion,            DateTime? vigenteHasta,            int? tipoAnuncioID,            string? tipoAnuncio,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "AnuncioID, Titulo, Contenido, FechaPublicacion, VigenteHasta, TipoAnuncioID, TipoAnuncio, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM anm.vsAnuncios (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (anuncioID.HasValue)            {                vSql.Append(" AND AnuncioID = @AnuncioID");                vParameters.Add("AnuncioID",anuncioID);            }            if (!string.IsNullOrWhiteSpace(titulo))            {                vSql.Append(" AND Titulo LIKE @Titulo");                vParameters.Add("Titulo",$"%{titulo}%");            }            if (!string.IsNullOrWhiteSpace(contenido))            {                vSql.Append(" AND Contenido LIKE @Contenido");                vParameters.Add("Contenido",$"%{contenido}%");            }            if (!string.IsNullOrWhiteSpace(tipoAnuncio))            {                vSql.Append(" AND TipoAnuncio LIKE @TipoAnuncio");                vParameters.Add("TipoAnuncio",$"%{tipoAnuncio}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadAnuncios> CreateAnuncios(clCreateAnuncios objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO anm.Anuncios                (Titulo, Contenido, FechaPublicacion, VigenteHasta, TipoAnuncioID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Titulo, @Contenido, @FechaPublicacion, @VigenteHasta, @TipoAnuncioID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Titulo,                objInput.Contenido,                objInput.FechaPublicacion,                objInput.VigenteHasta,                objInput.TipoAnuncioID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT AnuncioID, Titulo, Contenido, FechaPublicacion, VigenteHasta, TipoAnuncioID, TipoAnuncio, bEliminado                FROM anm.vsAnuncios (NOLOCK)                WHERE AnuncioID = @AnuncioID;";            var vReadParams = new { AnuncioID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadAnuncios>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Anuncio con ID {vNewId}.");            return vCreated;        }        public async Task<clReadAnuncios?> UpdateAnuncios(clUpdateAnuncios objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("AnuncioID", objInput.AnuncioID);            if (objInput.Titulo is not null)            {                vSets.Add("Titulo = @Titulo");                vParameters.Add("Titulo", objInput.Titulo);            }            if (objInput.Contenido is not null)            {                vSets.Add("Contenido = @Contenido");                vParameters.Add("Contenido", objInput.Contenido);            }            if (objInput.FechaPublicacion != null)            {                vSets.Add("FechaPublicacion = @FechaPublicacion");                vParameters.Add("FechaPublicacion", objInput.FechaPublicacion);            }            if (objInput.VigenteHasta != null)            {                vSets.Add("VigenteHasta = @VigenteHasta");                vParameters.Add("VigenteHasta", objInput.VigenteHasta);            }            if (objInput.TipoAnuncioID != null)            {                vSets.Add("TipoAnuncioID = @TipoAnuncioID");                vParameters.Add("TipoAnuncioID", objInput.TipoAnuncioID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE anm.Anuncios                SET {vSetClause}                WHERE AnuncioID = @AnuncioID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT AnuncioID, Titulo, Contenido, FechaPublicacion, VigenteHasta, TipoAnuncioID, TipoAnuncio, bEliminado                FROM anm.vsAnuncios (NOLOCK)                WHERE AnuncioID = @AnuncioID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadAnuncios>(sSelect, new {  objInput.AnuncioID });        }        public async Task<bool> DeleteAnuncios(int nAnunciosID)        {            const string sSql = @"                DELETE FROM anm.Anuncios                WHERE AnuncioID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nAnunciosID });            return vAffected > 0;        }    }}